        weights = [2, 3, 4, 5, 6, 7, 8, 9, 1, 0]
        total = 0
        for i in range(len(number)):
            digit = int(number[i])
            weight = weights[i]
            total += digit * weight
        return total % 11

    dv = calculate_dv(numero)
    if dv < 2:
        return '0'
    else:
        return str(11 - dv)
